WITH flattened_attrs AS (SELECT id, latency_ms, payload_json, SHIFTRIGHT(status_code, 2) AS status_code_high, context['region'] AS region FROM app_logs) SELECT id, latency_ms, status_code_high, RANK() OVER (ORDER BY latency_ms DESC NULLS FIRST) AS latency_ms_rank, FIRST_VALUE(region, TRUE) OVER (ORDER BY latency_ms, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_region, CUME_DIST() OVER (ORDER BY latency_ms NULLS LAST) AS latency_ms_cume_dist, CUME_DIST() OVER (ORDER BY status_code_high NULLS FIRST) AS status_code_high_cume_dist, FIRST_VALUE(latency_ms, TRUE) OVER (ORDER BY status_code_high, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_latency_ms FROM flattened_attrs
